using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class JojoPQueueApkBuild {
  public static string Run() {
    EditorApplication.delayCall += BuildNow;
    return "apk-queued";
  }
  static void BuildNow() {
    EditorUserBuildSettings.development = false;
    EditorUserBuildSettings.buildAppBundle = false;
    const string scenePath = "Assets/Scenes/Bootstrap.unity";
    var scene = EditorSceneManager.OpenScene(scenePath);
    foreach (var mb in Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None)) {
      if (mb.GetType().Name != "AppLauncher") continue;
      var so = new SerializedObject(mb);
      var play = so.FindProperty("devDirectPlay");
      if (play != null && play.boolValue) {
        play.boolValue = false;
        so.ApplyModifiedPropertiesWithoutUndo();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        Debug.Log("[JojoP] APK: closed devDirectPlay");
      }
      break;
    }
    Directory.CreateDirectory("Builds/Android");
    string path = Path.Combine("Builds/Android", "JojoPStack.apk");
    var scenes = new List<string>();
    foreach (var s in EditorBuildSettings.scenes) if (s.enabled) scenes.Add(s.path);
    if (scenes.Count == 0) {
      scenes.Add("Assets/Scenes/Bootstrap.unity");
      scenes.Add("Assets/Scenes/Main.unity");
    }
    Debug.Log("[JojoP] APK build start → " + path);
    var report = BuildPipeline.BuildPlayer(new BuildPlayerOptions {
      scenes = scenes.ToArray(),
      locationPathName = path,
      target = BuildTarget.Android,
      options = BuildOptions.None
    });
    Debug.Log("[JojoP] APK result=" + report.summary.result + " path=" + path + " time=" + report.summary.totalTime);
  }
}
